/bin/bash -c "node --input-type=module -e '
import { checkout } from \"./client.mjs\"
import { startOrderServer } from \"./server.mjs\"

const conditions = [
  { name: \"quote-80ms\", delay: \"80\" },
  { name: \"quote-0ms-control\", delay: \"0\" },
]

function summarize(values) {
  const sorted = [...values].sort((left, right) => left - right)
  const middle = Math.floor(sorted.length / 2)
  const median = sorted.length % 2 === 1
    ? sorted[middle]
    : (sorted[middle - 1] + sorted[middle]) / 2
  return {
    medianMs: Number(median.toFixed(3)),
    minMs: Number(sorted[0].toFixed(3)),
    maxMs: Number(sorted.at(-1).toFixed(3)),
  }
}

async function measure(url, condition) {
  process.env.EXTERNAL_DELAY_MS = condition.delay
  const { body, totalMs } = await checkout(url)
  return {
    totalMs: Number(totalMs.toFixed(3)),
    externalMs: Number(body.phases.externalMs.toFixed(3)),
    localMs: Number(body.phases.localMs.toFixed(3)),
    clientAndHttpRemainderMs: Number((totalMs - body.phases.externalMs - body.phases.localMs).toFixed(3)),
  }
}

const { server, url } = await startOrderServer()
try {
  const warmups = []
  for (const condition of conditions) {
    warmups.push({ condition: condition.name, ...(await measure(url, condition)) })
  }

  const measured = Object.fromEntries(conditions.map(({ name }) => [name, []]))
  for (let round = 0; round < 7; round += 1) {
    const order = round % 2 === 0 ? conditions : [...conditions].reverse()
    for (const condition of order) {
      measured[condition.name].push(await measure(url, condition))
    }
  }

  const report = Object.fromEntries(
    Object.entries(measured).map(([name, samples]) => [
      name,
      {
        n: samples.length,
        samples,
        total: summarize(samples.map((sample) => sample.totalMs)),
        external: summarize(samples.map((sample) => sample.externalMs)),
        local: summarize(samples.map((sample) => sample.localMs)),
        clientAndHttpRemainder: summarize(samples.map((sample) => sample.clientAndHttpRemainderMs)),
      },
    ]),
  )
  console.log(JSON.stringify({ warmups, report }, null, 2))
} finally {
  await new Promise((resolve) => server.close(resolve))
}
'"

